import{_ as a,c as i,a2 as s,o as t}from"./chunks/framework.BQmytedh.js";const k=JSON.parse('{"title":"Configure ALTCHA bot protection","description":"","frontmatter":{"prev":{"text":"Set upload limits","link":"/doc/faqs/admin/setup-upload-limits"},"next":{"text":"Errors","link":"/doc/faqs/error"}},"headers":[],"relativePath":"doc/faqs/admin/configure-altcha-protection.md","filePath":"doc/faqs/admin/configure-altcha-protection.md"}'),n={name:"doc/faqs/admin/configure-altcha-protection.md"};function l(o,e,r,h,p,c){return t(),i("div",null,e[0]||(e[0]=[s(`<h1 id="configure-altcha-bot-protection" tabindex="-1">Configure ALTCHA bot protection <a class="header-anchor" href="#configure-altcha-bot-protection" aria-label="Permalink to &quot;Configure ALTCHA bot protection&quot;">​</a></h1><p>ioChem-BD includes ALTCHA protection to defend against automated bot attacks and abuse. ALTCHA is a proof-of-work challenge system that requires clients to solve a computational puzzle before accessing protected pages, effectively blocking malicious bots while remaining transparent to legitimate users.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The ALTCHA filter operates in two modes:</p><p><strong>Normal mode (default)</strong></p><p>In normal mode, ALTCHA protection is only applied to search pages (<code>/simple-search</code> and handle-based search URLs). The filter monitors the number of query parameters in each request. When a search request contains more parameters than the configured threshold (default: 12), the user is redirected to an ALTCHA verification page.</p><p>This approach targets automated attacks that typically send requests with many parameters to exploit search functionality or cause excessive server load.</p><p><strong>Under Attack mode</strong></p><p>When enabled, ALTCHA verification is required for all pages except essential static resources. This mode is useful during active bot attacks or periods of heavy abuse when broader protection is needed.</p><p>Static resources like images, CSS, JavaScript, and help files are automatically excluded to ensure normal page rendering.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>ALTCHA protection is configured in <em>BASE_PATH/browse/config/dspace.cfg</em>, where <em>BASE_PATH</em> is the base folder where ioChem-BD software is installed.</p><h3 id="available-properties" tabindex="-1">Available properties <a class="header-anchor" href="#available-properties" aria-label="Permalink to &quot;Available properties&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Enable Under Attack mode (default: false)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># When true, ALTCHA check is applied to all pages, not just search pages</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">altcha.under.attack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Maximum query parameters before triggering ALTCHA (default: 12)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Requests exceeding this limit will require ALTCHA verification</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">altcha.max.query.params</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span></span></code></pre></div><h2 id="enabling-under-attack-mode" tabindex="-1">Enabling Under Attack mode <a class="header-anchor" href="#enabling-under-attack-mode" aria-label="Permalink to &quot;Enabling Under Attack mode&quot;">​</a></h2><p>During an active attack or abuse period, you can enable Under Attack mode to require ALTCHA verification on all pages:</p><ol><li><p>Edit <em>BASE_PATH/browse/config/dspace.cfg</em></p></li><li><p>Set the property:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">altcha.under.attack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div></li><li><p>Restart the ioChem-BD services to apply changes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iochembd$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  BASE_PATH/apache-tomcat/bin/shutdown.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -force</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iochembd$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  BASE_PATH/apache-tomcat/bin/startup.sh</span></span></code></pre></div></li><li><p>Monitor your server logs for the confirmation message:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  AltchaFilter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALTCHA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> under</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENABLED</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pages</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> will</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> be</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checked</span></span></code></pre></div></li></ol><h2 id="disabling-under-attack-mode" tabindex="-1">Disabling Under Attack mode <a class="header-anchor" href="#disabling-under-attack-mode" aria-label="Permalink to &quot;Disabling Under Attack mode&quot;">​</a></h2><p>Once the attack has subsided, disable Under Attack mode to return to normal operation:</p><ol><li><p>Edit <em>BASE_PATH/browse/config/dspace.cfg</em></p></li><li><p>Set the property:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">altcha.under.attack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span></span></code></pre></div></li><li><p>Restart the ioChem-BD services</p></li></ol><h2 id="adjusting-sensitivity" tabindex="-1">Adjusting sensitivity <a class="header-anchor" href="#adjusting-sensitivity" aria-label="Permalink to &quot;Adjusting sensitivity&quot;">​</a></h2><p>The <code>altcha.max.query.params</code> property controls how sensitive the filter is in normal mode. Lower values trigger ALTCHA more frequently, while higher values are more permissive.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># More sensitive - triggers on requests with more than 8 parameters</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">altcha.max.query.params</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Less sensitive - triggers on requests with more than 20 parameters</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">altcha.max.query.params</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The maximum allowed value is 39. Values of 40 or higher are automatically reduced to 30.</p></div><h2 id="excluded-paths" tabindex="-1">Excluded paths <a class="header-anchor" href="#excluded-paths" aria-label="Permalink to &quot;Excluded paths&quot;">​</a></h2><p>The following paths are always excluded from ALTCHA verification to ensure proper functionality:</p><p><strong>Exact paths:</strong></p><ul><li><code>/</code> - Homepage</li><li><code>/home.jsp</code> - Homepage (JSP)</li><li><code>/index.jsp</code> - Index page</li><li><code>/altcha-verify</code> - ALTCHA verification endpoint</li><li><code>/altcha-challenge</code> - ALTCHA challenge endpoint</li><li><code>/favicon.ico</code> - Site favicon</li><li><code>/robots.txt</code> - Search engine robots file</li><li><code>/cas-login</code> - CAS authentication endpoint</li></ul><p><strong>Path prefixes (directories):</strong></p><ul><li><code>/static/</code> - Static resources (CSS, JS)</li><li><code>/image/</code> - Image files</li><li><code>/css/</code> - Stylesheets</li><li><code>/xslt/</code> - Chemistry visualization tools</li><li><code>/help/</code> - Help documentation</li><li><code>/retrieve</code> - File retrieval endpoints</li><li><code>/mydspace</code> - User workspace</li></ul><p><strong>File extensions:</strong></p><ul><li>Files ending in <code>.js</code> - JavaScript files</li></ul><h2 id="altcha-difficulty-scaling" tabindex="-1">ALTCHA difficulty scaling <a class="header-anchor" href="#altcha-difficulty-scaling" aria-label="Permalink to &quot;ALTCHA difficulty scaling&quot;">​</a></h2><p>The ALTCHA challenge difficulty automatically scales based on the number of query parameters detected. Requests with more parameters receive harder challenges, making it progressively more expensive for attackers to abuse the system while keeping the challenge trivial for legitimate users.</p><ul><li>Normal requests: Base difficulty (100,000 iterations)</li><li>Excessive parameters: Scaled difficulty up to 1,000,000 iterations</li><li>Under Attack mode: Maximum difficulty for all checked requests</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Users report being asked to solve ALTCHA repeatedly</strong></p><p>This may indicate that cookies are not being preserved between requests. Ensure that the browser accepts cookies from your ioChem-BD domain. The ALTCHA verification is stored in the user&#39;s session.</p><p><strong>ALTCHA is not triggering during an attack</strong></p><p>Verify that Under Attack mode is enabled in the configuration and that the service was restarted. Check the server logs for the &quot;ALTCHA under attack mode is ENABLED&quot; message.</p><p><strong>Static resources are requiring ALTCHA verification</strong></p><p>Ensure the resources are served from one of the excluded paths. If you have custom static resource directories, they may need to be added to the filter&#39;s exclusion list.</p><hr><p>Please contact us at <a href="mailto:contact@iochem-bd.org" target="_blank" rel="noreferrer">contact@iochem-bd.org</a> for further assistance with ALTCHA protection configuration.</p>`,44)]))}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
